parameters.jsCode:
const item = $input.item.json;
if (item.error) {
  const msg = typeof item.error === 'string' ? item.error : JSON.stringify(item.error);
  return { json: { error: msg } };
}
try {
  let text = item.candidates[0].content.parts[0].text;
  text = text.replace(/^\s*`{3}(?:json)?\s*/i, '').replace(/`{3}\s*$/, '').trim();
  const parsed = JSON.parse(text);
  if (!parsed.categoria || !parsed.respuesta_borrador) throw new Error('faltan claves categoria/respuesta_borrador');
  return { json: { error: '', categoria: parsed.categoria, respuesta_borrador: parsed.respuesta_borrador } };
} catch (e) {
  return { json: { error: 'No se pudo parsear la respuesta de Gemini: ' + e.message } };
}
